const request = $input.first().json.body;
if (request?.action !== 'prepare-campaign' || !Array.isArray(request.groups) || !request.groups.length) {
  throw new Error('Вебхук ожидает запрос prepare-campaign с группами объявлений.');
}
return request.groups.map(group => ({json: {
  id: group.id,
  context: {
    project: request.project,
    campaignTemplate: request.campaignTemplate,
    settings: request.settings,
    group: {...group, keywords: group.keywords.slice(0, 20)}
  }
}}));

const groups = $('Подготовить группы').all();
const results = $input.all();
if (groups.length !== results.length) throw new Error('Claude вернул неполный набор групп.');
return [{json: {
  version: 1,
  groups: results.map(({json}, index) => {
    const raw = json.content?.find(block => block.type === 'text')?.text ?? '';
    let parsed;
    try { parsed = JSON.parse(raw.trim().replace(/^```(?:json)?s*|s*```$/gi, '')); }
    catch { throw new Error('Claude вернул некорректный JSON для группы «' + groups[index].json.context.group.name + '».'); }
    return {id: groups[index].json.id, title: parsed?.title, description: parsed?.description, negative: parsed?.negative};
  })
}}];
